"use client";

import { useState, useMemo, useEffect, useRef, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  CategorySlug,
  MOCK_PRODUCTS,
  CATEGORY_FILTERS,
  filterProducts,
} from "@/data/store-data";
import brandLogos from "@/data/brandLogos";
import { 
  ChevronDown, 
  SlidersHorizontal, 
  ArrowUpDown, 
  Check, 
  Play, 
  Square,
  Zap
} from "lucide-react";

const SORT_OPTIONS = [
  { label: "Newest Arrivals", value: "newest" },
  { label: "Best Sellers", value: "most-sold" },
  { label: "Most Popular", value: "most-liked" },
  { label: "Highest Discount", value: "most-offered" },
  { label: "Price: Low to High", value: "price-asc" },
  { label: "Price: High to Low", value: "price-desc" },
];

const COLOR_MAP: Record<string, string> = {
  Black: "#000000", White: "#ffffff", Blue: "#1d4ed8", 
  Grey: "#71717a", Red: "#dc2626", Green: "#15803d", Gold: "#fbbf24",
};

// --- REUSABLE ACCORDION SECTION ---
function SidebarAccordion({ title, children, isOpen, onToggle }: any) {
  return (
    <div className="border-b border-border py-4">
      <button
        onClick={onToggle}
        className="flex w-full items-center justify-between text-[11px] font-black uppercase tracking-[0.15em] text-foreground outline-none py-2"
      >
        <span>{title}</span>
        <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-500 ${isOpen ? "rotate-180" : ""}`} />
      </button>
      <AnimatePresence initial={false}>
        {isOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3, ease: "circOut" }}
            className="overflow-hidden"
          >
            <div className="pt-4 pb-2">{children}</div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default function CategoryClient({ category }: { category: CategorySlug }) {
  // --- DATA & STATE ---
  const products = useMemo(() => {
    const raw = MOCK_PRODUCTS.filter((p) => p.category === category);
    return Array.from(new Map(raw.map(item => [item.id, item])).values());
  }, [category]);

  const maxPriceLimit = useMemo(() => {
    if (products.length === 0) return 10000;
    return Math.ceil(Math.max(...products.map(p => p.price)) / 1000) * 1000;
  }, [products]);

  const [activeDrawer, setActiveDrawer] = useState<"filter" | "sort" | null>(null);
  const [openSections, setOpenSections] = useState<Record<string, boolean>>({ 
    sort: true, priceRange: true, brand: true, quality: true 
  });
  
  const [activeFilters, setActiveFilters] = useState<Record<string, string[]>>({ priceRange: [`0-${maxPriceLimit}`] });
  const [stagedFilters, setStagedFilters] = useState<Record<string, string[]>>({ priceRange: [`0-${maxPriceLimit}`] });
  const [sortBy, setSortBy] = useState("newest");

  // --- AUTO SCROLL LOGIC ---
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);
  const scrollRequestId = useRef<number | null>(null);
  const isEnabled = useRef(false);

  const stopAutoScroll = useCallback(() => {
    isEnabled.current = false;
    setIsAutoScrolling(false);
    if (scrollRequestId.current !== null) {
      cancelAnimationFrame(scrollRequestId.current);
      scrollRequestId.current = null;
    }
  }, []);

  const startAutoScroll = useCallback(() => {
    if (isEnabled.current) return;
    isEnabled.current = true;
    setIsAutoScrolling(true);
    const performScroll = () => {
      if (!isEnabled.current) return;
      window.scrollBy(0, 2);
      if ((window.innerHeight + window.scrollY) >= document.body.offsetHeight - 5) { stopAutoScroll(); return; }
      scrollRequestId.current = requestAnimationFrame(performScroll);
    };
    scrollRequestId.current = requestAnimationFrame(performScroll);
  }, [stopAutoScroll]);

  useEffect(() => {
    const triggerStop = () => { if (isEnabled.current) stopAutoScroll(); };
    window.addEventListener("touchstart", triggerStop, { passive: true });
    window.addEventListener("wheel", triggerStop, { passive: true });
    return () => {
      window.removeEventListener("touchstart", triggerStop);
      window.removeEventListener("wheel", triggerStop);
    };
  }, [stopAutoScroll]);

  // --- UI HELPERS ---
  const toggleSection = (id: string) => {
    setOpenSections(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const handleFilterChange = (id: string, opt: string, range: boolean) => {
    const updater = (prev: Record<string, string[]>) => {
      const cur = prev[id] || [];
      if (range) return { ...prev, [id]: [opt] };
      return cur.includes(opt) ? { ...prev, [id]: cur.filter(i => i !== opt) } : { ...prev, [id]: [...cur, opt] };
    };
    setStagedFilters(prev => updater(prev));
    if (typeof window !== "undefined" && window.innerWidth >= 1024) {
      setActiveFilters(prev => updater(prev));
    }
  };

  const availableFilters = CATEGORY_FILTERS[category] || [];
  const filteredAndSortedProducts = useMemo(() => {
    let result = filterProducts(products, activeFilters);
    const sorted = [...result];
    if (sortBy === "price-asc") sorted.sort((a, b) => a.price - b.price);
    else if (sortBy === "price-desc") sorted.sort((a, b) => b.price - a.price);
    else if (sortBy === "most-sold") sorted.sort((a, b) => (b.salesCount || 0) - (a.salesCount || 0));
    else if (sortBy === "most-liked") sorted.sort((a, b) => (b.popularityScore || 0) - (a.popularityScore || 0));
    else if (sortBy === "most-offered") sorted.sort((a, b) => (b.discount || 0) - (a.discount || 0));
    return sorted;
  }, [products, activeFilters, sortBy]);

  return (
    <div className="bg-background min-h-screen text-foreground transition-colors duration-500 pb-24">
      
      {/* MOBILE ONLY ACTION BAR */}
      <div className="sticky top-16 z-30 bg-background border-y border-border lg:hidden">
        <div className="max-w-7xl mx-auto flex h-12">
          <button onClick={() => setActiveDrawer("filter")} className="flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest border-r border-border hover:bg-background-muted transition-all">
            <SlidersHorizontal size={13} /> Filter
          </button>
          <button onClick={() => isAutoScrolling ? stopAutoScroll() : startAutoScroll()} className="flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest border-r border-border transition-all">
            {isAutoScrolling ? <Square size={12} fill="currentColor" className="text-brand"/> : <Play size={12} fill="currentColor"/>} Stop
          </button>
          <button onClick={() => setActiveDrawer("sort")} className="flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest hover:bg-background-muted transition-all">
            <ArrowUpDown size={13} /> Sort
          </button>
        </div>
      </div>

      <div className="max-w-7xl mx-auto flex px-4 lg:px-8 py-8 gap-16">
        
        {/* DESKTOP SIDEBAR (Unified Filters + Sort + Scroll) */}
        <aside className="hidden lg:block w-72 shrink-0 sticky top-32 h-[calc(100vh-140px)] overflow-y-auto no-scrollbar pb-10">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-[14px] font-black uppercase italic tracking-[0.25em]">Refine</h2>
            <button onClick={() => setActiveFilters({ priceRange: [`0-${maxPriceLimit}`] })} className="text-[10px] font-bold text-foreground-subtle hover:text-brand transition-colors">Reset</button>
          </div>

          <div className="space-y-2">
            {/* AUTO SCROLL SECTION */}
            <div className="bg-background-muted rounded-3xl p-4 mb-6 border border-border/50">
              <p className="text-[9px] font-black uppercase tracking-widest text-foreground-subtle mb-3 px-1 flex items-center gap-2">
                <Zap size={10} className="text-brand fill-brand" /> Experience Mode
              </p>
              <button 
                onClick={() => isAutoScrolling ? stopAutoScroll() : startAutoScroll()}
                className={`w-full py-3 rounded-2xl flex items-center justify-center gap-3 transition-all duration-500 border ${isAutoScrolling ? 'bg-brand text-brand-foreground border-brand shadow-lg shadow-brand/20' : 'bg-background border-border hover:border-foreground/20'}`}
              >
                {isAutoScrolling ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                <span className="text-[11px] font-black uppercase tracking-widest">{isAutoScrolling ? "Stop Scrolling" : "Auto Scroll"}</span>
              </button>
            </div>

            {/* SORT SECTION */}
            <SidebarAccordion title="Sort Selection" isOpen={openSections.sort} onToggle={() => toggleSection('sort')}>
              <div className="space-y-1">
                {SORT_OPTIONS.map((opt) => (
                  <button 
                    key={opt.value} 
                    onClick={() => setSortBy(opt.value)}
                    className={`w-full text-left py-2 px-3 rounded-xl text-[10px] font-bold uppercase tracking-tight transition-all ${sortBy === opt.value ? 'bg-foreground text-background font-black' : 'text-foreground-subtle hover:text-foreground hover:bg-background-muted'}`}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            </SidebarAccordion>

            {/* BUDGET RANGE SECTION */}
            <SidebarAccordion title="Budget Range" isOpen={openSections.priceRange} onToggle={() => toggleSection('priceRange')}>
              <div className="px-1">
                <div className="flex justify-between mb-4">
                  <span className="text-[9px] font-black text-foreground-subtle">₹0</span>
                  <span className="text-[10px] font-black text-brand uppercase">Under ₹{activeFilters.priceRange?.[0]?.split('-')[1]}</span>
                </div>
                <input
                  type="range" min="0" max={maxPriceLimit} step="100"
                  value={activeFilters.priceRange?.[0]?.split('-')[1] || maxPriceLimit}
                  onChange={(e) => handleFilterChange('priceRange', `0-${e.target.value}`, true)}
                  className="w-full h-1 bg-background-muted rounded-full appearance-none cursor-pointer accent-brand"
                />
              </div>
            </SidebarAccordion>

            {/* DYNAMIC CATEGORY FILTERS */}
            {availableFilters.filter(f => f.id !== 'gender').map((section) => (
              <SidebarAccordion 
                key={section.id} 
                title={section.label} 
                isOpen={openSections[section.id]} 
                onToggle={() => toggleSection(section.id)}
              >
                <div className="flex flex-wrap gap-2">
                  {section.options.map((opt: string) => {
                    const isChecked = (activeFilters[section.id] || []).includes(opt);
                    const brandObj = section.id === "brand" ? brandLogos.find(b => b.name.toLowerCase() === opt.toLowerCase()) : null;
                    return (
                      <button
                        key={opt}
                        onClick={() => handleFilterChange(section.id, opt, false)}
                        className={`flex items-center gap-2 px-3 py-2 rounded-full border text-[9px] font-black uppercase tracking-wider transition-all duration-300 ${isChecked ? "bg-foreground text-background border-foreground shadow-md" : "bg-background border-border text-foreground hover:border-foreground/30"}`}
                      >
                        {brandObj && <img src={brandObj.link} alt="" className={`w-4 object-contain ${isChecked ? "brightness-0 invert-0" : "dark:invert"}`} />}
                        {opt}
                      </button>
                    );
                  })}
                </div>
              </SidebarAccordion>
            ))}
          </div>
        </aside>

        {/* PRODUCT GRID MAIN AREA */}
        <main className="flex-1">
          <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-x-4 gap-y-10 sm:gap-x-8">
            <AnimatePresence mode="popLayout">
              {filteredAndSortedProducts.map((product) => (
                <motion.div layout initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} key={product.id} className="group cursor-pointer">
                  <div className="aspect-4/5 overflow-hidden rounded-[2rem] bg-background-muted border border-border/50 relative shadow-sm">
                    <img src={product.image || "/images/placeholder.png"} alt={product.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                    {product.isSale && <span className="absolute top-3 left-3 bg-brand text-brand-foreground text-[8px] font-black px-2 py-1 rounded-full uppercase shadow-sm">Sale</span>}
                  </div>
                  <div className="mt-4 px-1 space-y-1">
                    <div className="flex justify-between items-center mb-0.5">
                      <p className="text-[8px] font-black text-foreground-subtle uppercase tracking-widest">{product.brand}</p>
                      <span className="text-[7px] font-bold border border-border px-1.5 py-0.5 rounded-full text-foreground-subtle uppercase">{product.quality}</span>
                    </div>
                    <h2 className="text-[11px] font-bold uppercase truncate tracking-tight text-foreground">{product.name}</h2>
                    <p className="text-[10px] font-black text-foreground">₹{product.price.toLocaleString()}</p>
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        </main>
      </div>

      {/* MOBILE DRAWERS (EXISTING LOGIC REMAINS) */}
      <AnimatePresence>
        {activeDrawer && (
          <>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setActiveDrawer(null)} className="fixed inset-0 z-[60] bg-background/60 backdrop-blur-sm lg:hidden" />
            <motion.div
              initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }}
              transition={{ type: "tween", duration: 0.45, ease: [0.32, 0.72, 0, 1] }}
              drag="y" dragConstraints={{ top: 0, bottom: 0 }} dragElastic={{ top: 0, bottom: 0.8 }}
              onDragEnd={(_, info) => { if (info.offset.y > 60 || info.velocity.y > 400) setActiveDrawer(null); }}
              className="fixed bottom-0 left-0 right-0 z-[70] bg-background-elevated border-t border-border rounded-t-[3rem] max-h-[85vh] flex flex-col shadow-2xl lg:hidden touch-none"
            >
               {/* Mobile Drawer content continues here ... */}
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </div>
  );
}